3	import { MessageType, PROTOCOL_VERSION } from "@pirate-sea-race/protocol";
4	import { MatchRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
5	import { HeadlessClient, sleep } from "@pirate-sea-race/test-tools";
6	
7	let server: RunningGameServer;
8	let endpoint: string;
9	const clients: HeadlessClient[] = [];
10	
11	async function track(client: Promise<HeadlessClient>): Promise<HeadlessClient> {
12	  const joined = await client;
13	  clients.push(joined);
14	  return joined;
15	}
16	
17	beforeAll(async () => {
18	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false });
19	  endpoint = `http://127.0.0.1:${server.port}`;
20	});
21	
22	afterEach(async () => {
23	  await Promise.all(clients.splice(0).map((client) => client.leave()));
24	});
25	
26	afterAll(async () => {
27	  await server.close();
28	});
29	
30	function roomOf(client: HeadlessClient): MatchRoom {
31	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as MatchRoom;
32	}
33	
34	describe("private match", () => {
35	  it("creates a custom match with a six-character code", async () => {
36	    const host = await track(HeadlessClient.create(endpoint));
37	    expect(host.code).toMatch(/^[A-Z0-9]{6}$/);
38	    expect(host.room.state.custom).toBe(true);
39	    expect(host.room.state.protocolVersion).toBe(PROTOCOL_VERSION);
40	    expect(host.playerCount).toBe(1);
41	  });
42	
